function initBackToTop(){const e=document.getElementById("btn-back-to-top");e&&(window.addEventListener("scroll",()=>{const t=document.body.scrollTop||document.documentElement.scrollTop;e.style.display=t>20?"flex":"none"}),e.addEventListener("click",()=>{window.scrollTo({top:0,behavior:"smooth"})}))}function initServiziToggle(){const e=document.getElementById("altriServizi"),t=document.getElementById("btnAltriServizi");e&&t&&(e.addEventListener("show.bs.collapse",()=>{t.textContent="Nascondi"}),e.addEventListener("hide.bs.collapse",()=>{t.textContent="Altri servizi"}))}document.addEventListener("DOMContentLoaded",()=>{initBackToTop(),initServiziToggle()});